# ──────────────────────────────────────────────
# Constants for Secure Deserialization
# ──────────────────────────────────────────────
MAX_RAW_MESSAGE_SIZE: int = 2_097_152  # 2 MB max raw incoming data
MAX_PAYLOAD_SIZE: int = 1_048_576      # 1 MB max payload after parsing
HMAC_SECRET_ENV_VAR: str = "MESH_HMAC_SECRET"
DEFAULT_TTL: int = 3
MAX_TTL: int = 10
MIN_TIMESTAMP: float = 946684800.0     # Year 2000
MAX_CLOCK_SKEW: float = 60.0           # 1 minute


