class MeshMessage(BaseModel):
    """Universal mesh message envelope with strict schema enforcement.
    
    All inter-node communication MUST pass through this schema to prevent
    type confusion, injection attacks, and data corruption.
    """
    
    message_type: str = Field(
        ...,
        pattern=r'^(heartbeat|discovery|task_request|task_response|error|sync)$',
        description="Type of mesh message"
    )
    sender_id: str = Field(
        ...,
        min_length=1,
        max_length=128,
        pattern=r'^[a-zA-Z0-9_-]+$',
        description="Sender node identifier"
    )
    recipient_id: Optional[str] = Field(
        default=None,
        min_length=1,
        max_length=128,
        pattern=r'^[a-zA-Z0-9_-]+$',
        description="Optional recipient for directed messages"
    )
    payload: Dict[str, Any] = Field(
        default_factory=dict,
        description="Message payload (will be validated by nested schema)"
    )
    timestamp: float = Field(
        default_factory=time.time,
        description="Unix timestamp of message creation"
    )
    ttl: int = Field(
        default=DEFAULT_TTL,
        ge=1,
        le=MAX_TTL,
        description="Time-to-live for gossip propagation"
    )
    signature: Optional[str] = Field(
        default=None,
        max_length=512,
        pattern=r'^[a-fA-F0-9]{64}$',
        description="SHA-256 HMAC signature for message authentication"
    )

    @field_validator('payload')
    @classmethod
    def validate_payload_size(cls, v: Dict[str, Any]) -> Dict[str, Any]:
        """Prevent memory exhaustion via oversized payloads."""
        serialized = orjson.dumps(v)
        if len(serialized) > MAX_PAYLOAD_SIZE:
            raise ValueError(
                f"Payload exceeds maximum size of {MAX_PAYLOAD_SIZE} bytes "
                f"({len(serialized)} bytes)"
            )
        return v

    @field_validator('timestamp')
    @classmethod
    def validate_timestamp(cls, v: float) -> float:
        """Prevent timestamp manipulation attacks."""
        now = time.time()
        if v > now + MAX_CLOCK_SKEW:
            raise ValueError(f"Timestamp {v} is too far in the future (max {now + MAX_CLOCK_SKEW})")
        if v < MIN_TIMESTAMP:
            raise ValueError(f"Timestamp {v} is too far in the past (min {MIN_TIMESTAMP})")
        return v

    @model_validator(mode='after')
    def validate_message_integrity(self) -> 'MeshMessage':
        """Cross-field validation for message consistency."""
        if self.recipient_id and self.message_type not in ('task_request', 'task_response'):
            raise ValueError(
                f"Recipient field only valid for directed messages, got {self.message_type}"
            )
        return self


