class SecureMeshDeserializer:
    """Thread-safe deserialization layer with schema enforcement.
    
    Usage:
        deserializer = SecureMeshDeserializer()
        message = deserializer.deserialize(raw_bytes)
        node = deserializer.deserialize_node(raw_bytes)
    """
    
    def __init__(self, max_message_size: int = MAX_RAW_MESSAGE_SIZE):
        self._max_message_size = max_message_size
        self._schema_cache: Dict[str, type] = {
            'mesh_message': MeshMessage,
            'mesh_node': MeshNodeSchema,
        }
    
    def deserialize(self, data: Union[bytes, str]) -> MeshMessage:
        """Securely deserialize raw bytes into validated MeshMessage.
        
        Args:
            data: Raw bytes or string from network socket
            
        Returns:
            Validated MeshMessage instance
            
        Raises:
            ValueError: If deserialization fails validation
            TypeError: If data type is invalid
        """
        if isinstance(data, str):
            data = data.encode('utf-8')
        
        if len(data) > self._max_message_size:
            raise ValueError(
                f"Message exceeds maximum size of {self._max_message_size} bytes "
                f"({len(data)} bytes)"
            )
        
        try:
            raw_dict = orjson.loads(data)
        except orjson.JSONDecodeError as e:
            logger.error(f"JSON deserialization failed: {e}")
            raise ValueError(f"Invalid JSON payload: {e}")
        
        # Enforce strict type checking on root object
        if not isinstance(raw_dict, dict):
            raise TypeError(f"Expected JSON object, got {type(raw_dict).__name__}")
        
        # Validate through Pydantic schema
        try:
            message = MeshMessage(**raw_dict)
        except Exception as e:
            logger.error(f"Schema validation failed: {e}")
            raise ValueError(f"Message failed schema validation: {e}")
        
        # Verify message signature if present
        if message.signature:
            self._verify_signature(message)
        
        return message
    
    def deserialize_node(self, data: Union[bytes, str]) -> MeshNodeSchema:
        """Securely deserialize raw bytes into validated MeshNodeSchema.
        
        Args:
            data: Raw bytes or string containing node registration data
            
        Returns:
            Validated MeshNodeSchema instance
        """
        if isinstance(data, str):
            data = data.encode('utf-8')
        
        if len(data) > self._max_message_size:
            raise ValueError(
                f"Node data exceeds maximum size of {self._max_message_size} bytes "
                f"({len(data)} bytes)"
            )
        
        try:
            raw_dict = orjson.loads(data)
        except orjson.JSONDecodeError as e:
            logger.error(f"Node JSON deserialization failed: {e}")
            raise ValueError(f"Invalid node JSON payload: {e}")
        
        if not isinstance(raw_dict, dict):
            raise TypeError(f"Expected JSON object for node data, got {type(raw_dict).__name__}")
        
        try:
            node = MeshNodeSchema(**raw_dict)
        except Exception as e:
            logger.error(f"Node schema validation failed: {e}")
            raise ValueError(f"Node data failed schema validation: {e}")
        
        return node
    
    def _verify_signature(self, message: MeshMessage) -> None:
        """Verify HMAC signature for authenticated messages.
        
        This prevents message forgery and replay attacks.
        """
        shared_secret = os.environ.get(HMAC_SECRET_ENV_VAR, '').encode('utf-8')
        if not shared_secret:
            logger.warning(f"No {HMAC_SECRET_ENV_VAR} configured, skipping signature verification")
            return
        
        # Reconstruct the signed payload (everything except signature)
        payload_dict = message.model_dump(exclude={'signature'})
        payload_bytes = orjson.dumps(payload_dict, option=orjson.OPT_SORT_KEYS)
        
        expected_signature = hmac.new(
            shared_secret,
            payload_bytes,
            hashlib.sha256
        ).hexdigest()
        
        if not hmac.compare_digest(expected_signature, message.signature):
            raise ValueError("Message signature verification failed — possible forgery detected")


