class MeshNode:
    """Secure mesh node with enforced deserialization.
    
    Represents a single agent in the P2P mesh fabric.
    All incoming data is validated through SecureMeshDeserializer
    before any processing occurs.
    """
    
    def __init__(self, node_id: str, host: str = "127.0.0.1", port: int = 0):
        self.node_id = node_id
        self.host = host
        self.port = port
        self.deserializer = SecureMeshDeserializer()
        self._running = False
        self._peers: Dict[str, 'MeshNode'] = {}
        self._pending_tasks: Dict[str, asyncio.Future] = {}
        self._node_info: Optional[MeshNodeSchema] = None
        self._embedding_skill = FastEmbeddingSkill()
        
        logger.info(f"MeshNode initialized: {node_id} @ {host}:{port}")
    
    async def handle_incoming_message(self, raw_data: bytes) -> None:
        """Handle incoming network data with secure deserialization.
        
        This is the primary entry point for all network traffic.
        Malformed or malicious data is rejected at the deserialization boundary.
        """
        try:
            # Secure deserialization is the FIRST line of defense
            message = self.deserializer.deserialize(raw_data)
            
            # Now safe to process the validated message
            await self._process_message(message)
            
        except (ValueError, TypeError) as e:
            logger.error(f"Rejected malicious message from network: {e}")
            # Do NOT process or store the invalid data
            return
    
    async def send_message(self, recipient_id: str, message_type: str, 
                          payload: Dict[str, Any]) -> None:
        """Send a message with automatic schema validation.
        
        Args:
            recipient_id: Target node identifier
            message_type: Type of message (heartbeat, discovery, etc.)
            payload: Message payload data
        """
        message = MeshMessage(
            message_type=message_type,
            sender_id=self.node_id,
            recipient_id=recipient_id,
            payload=payload
        )
        
        # Serialize through Pydantic to ensure outgoing data is valid
        raw_bytes = orjson.dumps(message.model_dump())
        
        # Send over network (implementation depends on transport layer)
        await self._network_send(recipient_id, raw_bytes)
    
    async def broadcast_message(self, message_type: str, payload: Dict[str, Any]) -> None:
        """Broadcast a message to all connected peers.
        
        Args:
            message_type: Type of message to broadcast
            payload: Message payload data
        """
        message = MeshMessage(
            message_type=message_type,
            sender_id=self.node_id,
            payload=payload
        )
        
        raw_bytes = orjson.dumps(message.model_dump())
        
        # Broadcast to all peers
        tasks = []
        for peer_id in self._peers:
            tasks.append(self._network_send(peer_id, raw_bytes))
        
        await asyncio.gather(*tasks, return_exceptions=True)
    
    async def _process_message(self, message: MeshMessage) -> None:
        """Process a validated mesh message.
        
        Args:
            message: Validated MeshMessage instance
        """
        if message.message_type == "heartbeat":
            await self._handle_heartbeat(message)
        elif message.message_type == "discovery":
            await self._handle_discovery(message)
        elif message.message_type == "task_request":
            await self._handle_task_request(message)
        elif message.message_type == "task_response":
            await self._handle_task_response(message)
        elif message.message_type == "error":
            await self._handle_error(message)
        elif message.message_type == "sync":
            await self._handle_sync(message)
        else:
            logger.warning(f"Unknown message type: {message.message_type}")
    
    async def _handle_heartbeat(self, message: MeshMessage) -> None:
        """Process heartbeat message from peer."""
        peer_id = message.sender_id
        if peer_id in self._peers:
            self._peers[peer_id]._node_info.last_heartbeat = message.timestamp
            logger.debug(f"Heartbeat received from {peer_id}")
    
    async def _handle_discovery(self, message: MeshMessage) -> None:
        """Process discovery message from peer."""
        # Respond with our node info
        if self._node_info:
            response_payload = self._node_info.model_dump()
            await self.send_message(
                recipient_id=message.sender_id,
                message_type="sync",
                payload=response_payload
            )
    
    async def _handle_task_request(self, message: MeshMessage) -> None:
        """Process task request from peer."""
        logger.info(f"Task request received from {message.sender_id}: {message.payload.get('task_type', 'unknown')}")
        # Task processing logic would go here
        # For now, acknowledge receipt
        await self.send_message(
            recipient_id=message.sender_id,
            message_type="task_response",
            payload={"status": "received", "task_id": message.payload.get("task_id")}
        )
    
    async def _handle_task_response(self, message: MeshMessage) -> None:
        """Process task response from peer."""
        task_id = message.payload.get("task_id")
        if task_id and task_id in self._pending_tasks:
            future = self._pending_tasks.pop(task_id)
            if not future.done():
                future.set_result(message.payload)
    
    async def _handle_error(self, message: MeshMessage) -> None:
        """Process error message from peer."""
        logger.error(f"Error from {message.sender_id}: {message.payload.get('error', 'unknown error')}")
    
    async def _handle_sync(self, message: MeshMessage) -> None:
        """Process sync message from peer."""
        try:
            node_data = MeshNodeSchema(**message.payload)
            self._peers[node_data.node_id] = MeshNode(
                node_id=node_data.node_id,
                host=node_data.host,
                port=node_data.port
            )
            self._peers[node_data.node_id]._node_info = node_data
            logger.info(f"Synced peer: {node_data.node_id}")
        except Exception as e:
            logger.error(f"Failed to sync peer from message: {e}")
    
    async def _network_send(self, recipient_id: str, data: bytes) -> None:
        """Send raw bytes to a peer over the network.
        
        This is a placeholder for the actual transport layer implementation.
        In production, this would use TCP, UDP, or a message queue.
        
        Args:
            recipient_id: Target node identifier
            data: Raw bytes to send
        """
        # Placeholder: In production, implement actual network transport
        logger.debug(f"Network send to {recipient_id}: {len(data)} bytes")
        # Actual implementation would use asyncio streams, WebSockets, or similar
        await asyncio.sleep(0)  # Yield control
    
    def register_node_info(self, node_info: MeshNodeSchema) -> None:
        """Register this node's information.
        
        Args:
            node_info: Validated MeshNodeSchema for this node
        """
        self._node_info = node_info
        logger.info(f"Node info registered: {node_info.node_id}")
    
    def add_peer(self, peer_node: 'MeshNode') -> None:
        """Add a peer to the mesh.
        
        Args:
            peer_node: MeshNode instance representing the peer
        """
        self._peers[peer_node.node_id] = peer_node
        logger.info(f"Peer added: {peer_node.node_id}")
    
    def remove_peer(self, peer_id: str) -> None:
        """Remove a peer from the mesh.
        
        Args:
            peer_id: Identifier of the peer to remove
        """
        if peer_id in self._peers:
            del self._peers[peer_id]
            logger.info(f"Peer removed: {peer_id}")
    
    @property
    def peers(self) -> Dict[str, 'MeshNode']:
        """Get the current peer map."""
        return dict(self._peers)
    
    @property
    def is_running(self) -> bool:
        """Check if the node is running."""
        return self._running


