class MeshManager:
    """Manages the P2P mesh topology and node lifecycle.
    
    Provides high-level operations for mesh discovery, registration,
    and task routing across the distributed fabric.
    """
    
    def __init__(self, node_id: str, host: str = "127.0.0.1", port: int = 0):
        self.local_node = MeshNode(node_id=node_id, host=host, port=port)
        self._discovery_task: Optional[asyncio.Task] = None
        self._heartbeat_task: Optional[asyncio.Task] = None
        logger.info(f"MeshManager initialized for node: {node_id}")
    
    async def start(self) -> None:
        """Start the mesh node and begin discovery/heartbeat loops."""
        self._discovery_task = asyncio.create_task(self._discovery_loop())
        self._heartbeat_task = asyncio.create_task(self._heartbeat_loop())
        logger.info("MeshManager started")
    
    async def stop(self) -> None:
        """Gracefully stop the mesh node."""
        if self._discovery_task:
            self._discovery_task.cancel()
        if self._heartbeat_task:
            self._heartbeat_task.cancel()
        logger.info("MeshManager stopped")
    
    async def _discovery_loop(self) -> None:
        """Periodically discover new peers on the mesh."""
        while True:
            try:
                # Broadcast discovery request
                await self.local_node.broadcast_message(
                    message_type="discovery",
                    payload={"node_id": self.local_node.node_id}
                )
                await asyncio.sleep(30)  # Discover every 30 seconds
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"Discovery loop error: {e}")
                await asyncio.sleep(60)  # Back off on error
    
    async def _heartbeat_loop(self) -> None:
        """Periodically send heartbeats to maintain mesh topology."""
        while True:
            try:
                await self.local_node.broadcast_message(
                    message_type="heartbeat",
                    payload={
                        "node_id": self.local_node.node_id,
                        "timestamp": time.time()
                    }
                )
                await asyncio.sleep(15)  # Heartbeat every 15 seconds
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"Heartbeat loop error: {e}")
                await asyncio.sleep(30)  # Back off on error
    
    async def route_task(self, task_type: str, payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Route a task to the most appropriate peer.
        
        Args:
            task_type: Type of task to route
            payload: Task payload data
            
        Returns:
            Task response payload, or None if no peer available
        """
        # Find best peer based on specialties/skills
        best_peer = None
        best_score = -1
        
        for peer_id, peer_node in self.local_node.peers.items():
            if peer_node._node_info:
                score = self._score_peer_for_task(peer_node._node_info, task_type)
                if score > best_score:
                    best_score = score
                    best_peer = peer_id
        
        if best_peer:
            # Create future for response
            task_id = hashlib.sha256(orjson.dumps(payload)).hexdigest()[:16]
            future = asyncio.get_event_loop().create_future()
            self.local_node._pending_tasks[task_id] = future
            
            # Send task request
            await self.local_node.send_message(
                recipient_id=best_peer,
                message_type="task_request",
                payload={"task_id": task_id, "task_type": task_type, **payload}
            )
            
            # Wait for response with timeout
            try:
                response = await asyncio.wait_for(future, timeout=30.0)
                return response
            except asyncio.TimeoutError:
                logger.warning(f"Task {task_id} timed out")
                return None
        
        logger.warning(f"No suitable peer found for task type: {task_type}")
        return None
    
    def _score_peer_for_task(self, node_info: MeshNodeSchema, task_type: str) -> int:
        """Score a peer's suitability for a given task type.
        
        Args:
            node_info: Peer's node information
            task_type: Type of task to score
            
        Returns:
            Integer score (higher = better match)
        """
        score = 0
        
        # Check specialties
        if task_type in node_info.specialties:
            score += 10
        
        # Check skills
        if task_type in node_info.skills:
            score += 5
        
        # Prefer less busy nodes
        score -= node_info.task_count // 10
        
        # Prefer nodes with more peer connections (better connected)
        score += node_info.peer_connections
        
        return score


